import React from 'react';
import { 
  Box, Card, CardContent, Typography, Chip, 
  Divider, LinearProgress, Tooltip, Accordion, AccordionSummary, AccordionDetails
} from '@mui/material';
import WarningIcon from '@mui/icons-material/Warning';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';

const ConversationChunk = ({ chunk, index, expanded, onChange }) => {
  const { isComplaint, confidence, utterances } = chunk;

  // Format confidence as percentage
  const confidencePercent = (confidence * 100).toFixed(1);

  // Determine color based on complaint status and confidence
  let statusColor, statusIcon, statusText;

  if (isComplaint) {
    statusColor = 'error';
    statusIcon = <WarningIcon fontSize="small" />;
    statusText = 'Complaint Detected';
  } else {
    statusColor = 'success';
    statusIcon = <CheckCircleIcon fontSize="small" />;
    statusText = 'No Complaint';
  }

  return (
    <Accordion 
      expanded={expanded}
      onChange={onChange}
      sx={{ 
        mb: 1,
        background: 'rgba(13, 2, 8, 0.7)',
        backdropFilter: 'blur(4px)',
        border: `1px solid ${isComplaint ? 'var(--bright-green)' : 'var(--dark-green)'}`,
        boxShadow: isComplaint ? '0 0 10px rgba(0, 255, 65, 0.3)' : 'none',
        transition: 'all 0.3s ease',
        '&:hover': {
          boxShadow: '0 0 15px rgba(0, 255, 65, 0.4)'
        }
      }}
    >
      <AccordionSummary 
        expandIcon={<ExpandMoreIcon sx={{ color: 'var(--neon-green)' }} />}
        sx={{
          borderBottom: expanded ? '1px solid var(--dark-green)' : 'none'
        }}
      >
        <Typography 
          sx={{ 
            fontFamily: 'monospace',
            fontWeight: isComplaint ? 'bold' : 'normal',
            color: 'var(--text-color)',
            textShadow: isComplaint ? '0 0 5px var(--neon-green)' : 'none',
            fontSize: '1.2rem'
          }}
        >
          CHUNK_{index + 1} {isComplaint ? '[COMPLAINT_DETECTED]' : '[STATUS_NORMAL]'} // 
          {new Date(chunk.timestamp).toLocaleTimeString()}
        </Typography>
      </AccordionSummary>
      <AccordionDetails>
        <Card 
          variant="outlined" 
          sx={{ 
            border: 'none',
            boxShadow: 'none',
            backgroundColor: 'transparent'
          }}
        >
          <CardContent sx={{ p: 1 }}>
            <Box sx={{ mb: 2 }}>
              <Tooltip title={`Confidence: ${confidencePercent}%`} arrow placement="top">
                <Box sx={{ width: '100%' }}>
                  <Typography variant="body2" sx={{ mb: 0.5, color: 'var(--text-color)', fontSize: '1.1rem' }}>
                    Confidence: {confidencePercent}%
                  </Typography>
                  <LinearProgress
                    variant="determinate"
                    value={confidence * 100}
                    sx={{ 
                      height: 8, 
                      borderRadius: 4,
                      backgroundColor: 'rgba(0, 255, 65, 0.1)',
                      '& .MuiLinearProgress-bar': {
                        backgroundColor: isComplaint ? 'var(--bright-green)' : 'var(--muted-green)'
                      }
                    }}
                  />
                </Box>
              </Tooltip>
            </Box>

            <Divider sx={{ my: 1, backgroundColor: 'var(--dark-green)' }} />

            <Box className="chat-container" sx={{ mt: 2 }}>
              {utterances.map((utterance, i) => (
                <Box 
                  key={i}
                  className={`utterance ${utterance.speaker}`}
                  sx={{ 
                    display: 'flex',
                    flexDirection: 'column',
                    mb: 2,
                    p: 2,
                    borderRadius: 2,
                    maxWidth: '80%',
                    backgroundColor: utterance.speaker === 'caller' 
                      ? 'rgba(0, 120, 20, 0.4)' 
                      : 'rgba(0, 80, 120, 0.4)',
                    alignSelf: utterance.speaker === 'caller' ? 'flex-start' : 'flex-end',
                    border: utterance.speaker === 'caller'
                      ? '2px solid rgba(0, 255, 65, 0.6)'
                      : '2px solid rgba(0, 180, 255, 0.6)',
                    boxShadow: utterance.speaker === 'caller'
                      ? '0 0 15px rgba(0, 255, 65, 0.3)'
                      : '0 0 15px rgba(0, 180, 255, 0.3)',
                    backdropFilter: 'blur(0px)',
                  }}
                >
                  <Typography 
                    variant="caption" 
                    sx={{ 
                      color: utterance.speaker === 'caller' ? '#39ff14' : '#00ffff',
                      fontWeight: 'bold',
                      textTransform: 'uppercase',
                      fontFamily: 'monospace',
                      fontSize: '1.1rem',
                      letterSpacing: '0.05em',
                      textShadow: utterance.speaker === 'caller' 
                        ? '0 0 8px rgba(57, 255, 20, 0.7)' 
                        : '0 0 8px rgba(0, 255, 255, 0.7)',
                      mb: 0.5
                    }}
                  >
                    {utterance.speaker}
                  </Typography>
                  <Typography 
                    variant="body2" 
                    sx={{ 
                      color: '#ffffff',
                      wordBreak: 'break-word',
                      fontSize: '1.1rem',
                      fontWeight: 'medium',
                      textShadow: '0 0 2px rgba(255, 255, 255, 0.7)',
                      lineHeight: 1.4
                    }}
                  >
                    {utterance.content}
                  </Typography>
                </Box>
              ))}
            </Box>
          </CardContent>
        </Card>
      </AccordionDetails>
    </Accordion>
  );
};

export default ConversationChunk;
